from typing import Callable, Any

def cached(cache: dict, key: Callable[[Any], str] = hashkey, lock=None) -> Callable[[Callable], Callable]:
    def decorator(func: Callable) -> Callable:
        @wraps(func)
        def wrapper(*args, **kwargs):
            if key is None:
                key = lambda x: x
            elif isinstance(key, str) and '=' in key:
                key = lambda x: x.split('=')[1]
            else:
                key = key

            if lock is not None:
                lock.acquire()
            try:
                result = cache.get(key(*args)(**kwargs))
                if result is not None:
                    return result
            except Exception as e:
                if lock is not None:
                    lock.release()
                    raise e
            result = func(*args, **kwargs)
            cache[key(*args)(**kwargs)] = result
            if lock is not None:
                lock.release()
            return result
        return wrapper
    return decorator
