from datetime import timedelta

def parse_frequency(frequency):
    """
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    """
    if frequency is None or frequency == "always":
        return None

    if " weeks" in frequency:
        return timedelta(weeks=int(frequency.split()[0]))
    elif " days" in frequency:
        return timedelta(days=int(frequency.split()[0]))
    elif " hours" in frequency:
        return timedelta(hours=int(frequency.split()[0]))
    elif " minutes" in frequency:
        return timedelta(minutes=int(frequency.split()[0]))
    elif " seconds" in frequency:
        return timedelta(seconds=int(frequency.split()[0]))
    else:
        raise ValueError("Unknown frequency unit")
