            if i + 1 < len(text) and text[i+1] != '/':
                j = i + 1
                while j < len(text) and text[j] != '>':
                    j += 1
                tag_name = text[i+1:j]
                if not codes[tag_name]:
                    tags.add(tag_name)
                    if j < len(text) and text[j] == '>':
                        i += 2
                    else:
                        raise ValueError('Invalid tag: ' + text[i:])
                else:
                    codes[tag_name].append(i)
                i = j + 1
            else:
                j = i + 2
                while j < len(text) and text[j] != '/':
                    j += 1
                tag_name = text[i+2:j]
                codes[tag_name].append(i + 2)
                i = j + 1

        elif text[i] == '>' and i + 1 < len(text):
            if text[i+1] == '/':
                i += 2
            else:
                match, i = find_matching_tag(text,i)
                if match is None:
                    raise ValueError('Unclosed tag: ' + text[i:])
                tags.add(match)
                i = i + len(match)

        elif text[i].isspace():
            i += 1
            continue

        else:
            j = i
            while j < len(text) and not text[j].isspace():
                j += 1
            if replacer and tags:
                text = text[:i] + replacer(text[i:j]) + text[j:]
            elif replacer:
                text = text[:i] + replacer(text[i:]) + text[j:]
            i = j
            codes.clear()

    return tags, text

def find_matching_tag(text: str, start: int) -> Tuple[str, int]:
    i = start
    stack = []

    while i < len(text):
        if text[i] == '<':
            stack.append(text[i+1])
        elif text[i] == '/':
            if not stack:
                return None, i  # unmatched closing tag
            stack.pop()
        elif not stack and text[i].isspace():
            return text[start:i].strip(), i  # reached the end of a tag
        elif not stack and i + 1 == len(text) or text[i + 1] != '>':
            return text[start:i].strip(), i  # reached the end of a tag
        i += 1

    return None, len(text)  # unmatched opening tag
